def run(db_path=None):
    db_path = db_path or os.environ.get("DB_PATH") or "academy.db"
    if not os.path.exists(db_path):
        print(f"[fill_r01_r24] DB not found: {db_path}")
        return
    con = sqlite3.connect(db_path)
    cur = con.cursor()
    updated = 0
    # تحديث فقط إذا المحتوى الحالي قصير (< 1000 حرف) لتجنب الكتابة فوق محتوى أحدث
    cur.execute("SELECT length(content) FROM lessons WHERE lesson_code='R-01'")
    row = cur.fetchone()
    if row and (row[0] or 0) < 1000:
        cur.execute("UPDATE lessons SET content=?, title_ar=?, focus_point=? WHERE lesson_code='R-01'",
                    (R01_CONTENT, R01_TITLE, R01_FOCUS))
        updated += cur.rowcount
    cur.execute("SELECT length(content) FROM lessons WHERE lesson_code='R-24'")
    row = cur.fetchone()
    if row and (row[0] or 0) < 1000:
        cur.execute("UPDATE lessons SET content=?, title_ar=?, focus_point=? WHERE lesson_code='R-24'",
                    (R24_CONTENT, R24_TITLE, R24_FOCUS))
        updated += cur.rowcount
    con.commit()
    con.close()
    print(f"[fill_r01_r24] updated={updated}")

if __name__ == "__main__":
    run(sys.argv[1] if len(sys.argv) > 1 else None)
